import{_ as r,o as t,c as a,ae as e}from"./chunks/framework.Dzr56EFm.js";const d=JSON.parse('{"title":"产品发布 - 2026-07-03","description":"","frontmatter":{"date":"2026-07-03T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-07-03-product.md","filePath":"daily/2026-07-03-product.md"}'),n={name:"daily/2026-07-03-product.md"};function s(p,o,i,l,g,h){return t(),a("div",null,[...o[0]||(o[0]=[e('<h1 id="产品发布-2026-07-03" tabindex="-1">产品发布 - 2026-07-03 <a class="header-anchor" href="#产品发布-2026-07-03" aria-label="Permalink to &quot;产品发布 - 2026-07-03&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域主要动态涉及AI助手和工作流更新。Notion扩展AI功能并更新API，数字.ai 23.3版本引入自助服务工作流。最值得关注的是微软Copilot系列AI工具，旨在提升组织效率和安全性，以及Product Copilot作为软件产品团队的AI助手，集成于Jira和Confluence中，提高团队效率。</p><hr><h3 id="_1-notion文档更新日志" tabindex="-1">1. Notion文档更新日志 <a class="header-anchor" href="#_1-notion文档更新日志" aria-label="Permalink to &quot;1. Notion文档更新日志&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://developers.notion.com/page/changelog" target="_blank" rel="noreferrer">Changelog - Notion Docs</a></p><p><strong>一句话摘要</strong>: Notion扩展AI助手功能并更新API。</p><p><strong>能解决什么问题</strong>: 提高Notion与AI助手集成的效率和灵活性。</p><p><strong>产品应用</strong>: 企业可通过AI助手直接查询数据库，提升工作效率。</p><p><strong>示例场景</strong>: 企业团队用AI助手查询项目进度。</p><hr><h3 id="_2-微软copilot-维基百科" tabindex="-1">2. 微软Copilot - 维基百科 <a class="header-anchor" href="#_2-微软copilot-维基百科" aria-label="Permalink to &quot;2. 微软Copilot - 维基百科&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://en.wikipedia.org/wiki/Microsoft_Copilot" target="_blank" rel="noreferrer">Microsoft Copilot - Wikipedia</a></p><p><strong>一句话摘要</strong>: 微软基于大型语言模型开发的AI聊天机器人</p><p><strong>能解决什么问题</strong>: 提供替代Cortana的智能助手服务</p><p><strong>产品应用</strong>: 可集成到Windows和Microsoft 365，适用于多种业务场景</p><p><strong>示例场景</strong>: 企业使用Copilot Studio创建定制AI助手</p><hr><h3 id="_3-数字-ai-23-3版本工作流概览" tabindex="-1">3. 数字.ai 23.3版本工作流概览 <a class="header-anchor" href="#_3-数字-ai-23-3版本工作流概览" aria-label="Permalink to &quot;3. 数字.ai 23.3版本工作流概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://docs.digital.ai/release/docs/how-to/workflows-overview" target="_blank" rel="noreferrer">Workflows Overview · digital.ai Release</a></p><p><strong>一句话摘要</strong>: 数字.ai 23.3版本引入自助服务工作流，简化应用部署。</p><p><strong>能解决什么问题</strong>: 帮助开发者在对工具知识有限的情况下轻松部署应用。</p><p><strong>产品应用</strong>: 适用于需要简化云应用部署和优化性能的企业。</p><p><strong>示例场景</strong>: 开发者使用工作流将代码从开发环境部署到生产环境。</p><hr><h3 id="_4-产品副驾驶——软件产品团队的ai助手" tabindex="-1">4. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_4-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;4. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，帮助产品团队提高效率。</p><p><strong>能解决什么问题</strong>: 解决产品团队在管理用户故事、协作和产品开发中的效率问题。</p><p><strong>产品应用</strong>: 适用于需要优化产品管理流程的软件团队，直接在Jira和Confluence中使用。</p><p><strong>示例场景</strong>: 产品负责人使用Product Copilot创建清晰的用户故事和维护文档。</p><hr><h3 id="_5-微软copilot-面向组织的ai工具" tabindex="-1">5. 微软Copilot | 面向组织的AI工具 <a class="header-anchor" href="#_5-微软copilot-面向组织的ai工具" aria-label="Permalink to &quot;5. 微软Copilot | 面向组织的AI工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/organizations" target="_blank" rel="noreferrer">Microsoft Copilot | AI Tools for Organizations</a></p><p><strong>一句话摘要</strong>: 微软Copilot系列AI工具，助力组织提升效率和安全性。</p><p><strong>能解决什么问题</strong>: 提高工作效率，加强数据安全，优化代码编写。</p><p><strong>产品应用</strong>: 适用于企业日常运营，安全防护，以及软件开发。</p><p><strong>示例场景</strong>: 企业使用Microsoft 365 Copilot提高文档处理效率。</p><hr><h3 id="_6-ai新闻-导致市场崩溃的ai产品发布" tabindex="-1">6. AI新闻：导致市场崩溃的AI产品发布 <a class="header-anchor" href="#_6-ai新闻-导致市场崩溃的ai产品发布" aria-label="Permalink to &quot;6. AI新闻：导致市场崩溃的AI产品发布&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=xdp8bulnidY&amp;vl=en-US" target="_blank" rel="noreferrer">AI News: The AI Launch That Crashed The Market - YouTube</a></p><p><strong>一句话摘要</strong>: 本周AI领域发生了许多重大新闻。</p><p><strong>能解决什么问题</strong>: 提供AI编程辅助、模型升级和视频工具改进。</p><p><strong>产品应用</strong>: 可以应用到编程、模型训练和视频制作等领域。</p><p><strong>示例场景</strong>: 开发者使用Codex app进行代码编写。</p><hr><h3 id="_7-谷歌在英国推出新的-ai模式-搜索功能" tabindex="-1">7. 谷歌在英国推出新的“AI模式”搜索功能 <a class="header-anchor" href="#_7-谷歌在英国推出新的-ai模式-搜索功能" aria-label="Permalink to &quot;7. 谷歌在英国推出新的“AI模式”搜索功能&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.bbc.com/news/articles/clyj4zky4zwo" target="_blank" rel="noreferrer">Google launches new &#39;AI mode&#39; search feature in UK</a></p><p><strong>一句话摘要</strong>: 谷歌在英国推出AI搜索功能，提供对话风格的答案。</p><p><strong>能解决什么问题</strong>: 解决传统搜索引擎无法提供快速、简单答案的问题。</p><p><strong>产品应用</strong>: 可以应用到搜索引擎中，提供更直观的对话式搜索结果。</p><p><strong>示例场景</strong>: 用户搜索“清洁地毯污渍”，得到直接的清洁方法。</p><hr><h3 id="_8-notion-3-4版本新特性概览" tabindex="-1">8. Notion 3.4版本新特性概览 <a class="header-anchor" href="#_8-notion-3-4版本新特性概览" aria-label="Permalink to &quot;8. Notion 3.4版本新特性概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=Z5hwjq5K0eY" target="_blank" rel="noreferrer">What&#39;s New in Notion 3.4 - YouTube</a></p><p><strong>一句话摘要</strong>: Notion 3.4版本引入了侧边栏、仪表板、演示模式等多项新功能。</p><p><strong>能解决什么问题</strong>: 提高工作效率，增强团队协作和信息管理。</p><p><strong>产品应用</strong>: 适用于需要高效信息管理和团队协作的企业或个人。</p><p><strong>示例场景</strong>: 团队使用Notion仪表板监控项目进度和关键指标。</p><hr><h3 id="_9-谷歌推出全新ai搜索功能" tabindex="-1">9. 谷歌推出全新AI搜索功能？！ <a class="header-anchor" href="#_9-谷歌推出全新ai搜索功能" aria-label="Permalink to &quot;9. 谷歌推出全新AI搜索功能？！&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.youtube.com/watch?v=X8n7ezdYuK4" target="_blank" rel="noreferrer">Google Launches a BRAND NEW AI Search?!</a></p><p><strong>一句话摘要</strong>: 谷歌发布AI模式，应对新兴AI搜索工具挑战。</p><p><strong>能解决什么问题</strong>: 应对传统搜索受到新兴AI工具威胁的问题。</p><p><strong>产品应用</strong>: 适用于快速适应变化的业务，提升SEO效果。</p><p><strong>示例场景</strong>: B2B和B2C品牌利用AI模式优化搜索排名。</p><hr><h3 id="_10-openai将发布ai浏览器挑战谷歌chrome" tabindex="-1">10. OpenAI将发布AI浏览器挑战谷歌Chrome <a class="header-anchor" href="#_10-openai将发布ai浏览器挑战谷歌chrome" aria-label="Permalink to &quot;10. OpenAI将发布AI浏览器挑战谷歌Chrome&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.reuters.com/business/media-telecom/openai-release-web-browser-challenge-google-chrome-2025-07-09" target="_blank" rel="noreferrer">OpenAI to release web browser in challenge to Google Chrome</a></p><p><strong>一句话摘要</strong>: OpenAI即将发布AI浏览器，挑战谷歌Chrome的市场地位。</p><p><strong>能解决什么问题</strong>: 提供更智能的网络浏览体验，获取用户数据。</p><p><strong>产品应用</strong>: 可应用于个人和工作生活，通过AI技术改善搜索和浏览效率。</p><p><strong>示例场景</strong>: 用户使用AI浏览器快速获取信息并进行决策。</p><hr>',75)])])}const u=r(n,[["render",s]]);export{d as __pageData,u as default};
